/**
 * `handle_description` on an update-record tool (skill or agent) is optional
 * on the wire: the platform accepts omitting it entirely (matching a legacy
 * record's `null`), but always rejects an explicit empty string at apply
 * with an opaque "Unable to validate" error - confirmed live against the
 * platform (edk#801). Authoring should catch that mistake immediately
 * rather than let it surface later during build.
 */
export function assertHandleDescriptionNotEmpty(value, where) {
    if (value === "") {
        throw new Error(`${where}'s handleDescription must not be an empty string - omit it entirely if there is no description.`);
    }
}
/** Sets `handle_description` only when there's a real value - omitting matches how the platform itself treats "no description." */
export function encodeOptionalHandleDescription(attrs, value) {
    if (value)
        attrs["handle_description"] = value;
}
